"""Adapt Coval voice simulation transcripts to eval-suite turn dicts."""

from __future__ import annotations

from typing import Any, Dict, List, Mapping, Optional, Sequence, Tuple

_TURN = "turn"
_USER = "user"
_BOT = "bot"
_TTFT_MS = "ttft_ms"
_TURN_LATENCY_MS = "turn_latency_ms"
_GAPS_MS = "gaps_ms"

_ROLE_ASSISTANT = "assistant"
_ROLE_USER = "user"

# Coval interleaves non-speech messages into the transcript (``system``, and
# ``tool`` when the simulated caller invokes something like ``silence_tool``
# mid-turn). Only these roles carry conversation audio; anything else is
# dropped before pairing so it cannot split a turn.
_SPEECH_ROLES = frozenset({_ROLE_ASSISTANT, _ROLE_USER})


def _extract_content(message: Mapping[str, Any]) -> str:
    """Return string content from a Coval transcript message."""
    content = message.get("content")
    if content is None:
        return ""
    if isinstance(content, str):
        return content.strip()
    if isinstance(content, dict):
        for key in ("text", "message", "content"):
            value = content.get(key)
            if isinstance(value, str) and value.strip():
                return value.strip()
        return ""
    return str(content).strip()


def _offset_seconds(value: Any) -> Optional[float]:
    """Parse a Coval timeline offset (seconds) from int/float fields."""
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        return None
    return float(value)


def _message_span_seconds(
    message: Mapping[str, Any],
) -> Tuple[Optional[float], Optional[float]]:
    """Return ``(start_offset, end_offset)`` in seconds when present."""
    return _offset_seconds(message.get("start_offset")), _offset_seconds(
        message.get("end_offset")
    )


def _latency_from_anchor_ms(
    *,
    anchor_s: Optional[float],
    first_start_s: Optional[float],
    last_end_s: Optional[float],
) -> Tuple[Optional[float], Optional[float]]:
    """Compute ttft / turn latency in ms relative to an anchor time in seconds.

    Coval voice transcripts use absolute call-timeline offsets. For a normal
    turn the anchor is the preceding user utterance's ``end_offset``; for the
    welcome turn the anchor is call start (``0``).
    """
    if anchor_s is None:
        return None, None

    ttft_ms: Optional[float] = None
    turn_latency_ms: Optional[float] = None
    if first_start_s is not None and first_start_s >= anchor_s:
        ttft_ms = (first_start_s - anchor_s) * 1000.0
    if last_end_s is not None and last_end_s >= anchor_s:
        turn_latency_ms = (last_end_s - anchor_s) * 1000.0
    return ttft_ms, turn_latency_ms


def _gaps_ms(
    bot_spans: List[Tuple[Optional[float], Optional[float]]],
) -> List[float]:
    """Return valid gaps between consecutive assistant audio responses."""
    gaps_ms: List[float] = []
    previous_end_s: Optional[float] = None
    for start_s, end_s in bot_spans:
        if start_s is None and end_s is None:
            continue
        if start_s is None or end_s is None:
            previous_end_s = None
            continue
        if previous_end_s is not None and start_s >= previous_end_s:
            gaps_ms.append((start_s - previous_end_s) * 1000.0)
        previous_end_s = end_s
    return gaps_ms


def _collect_assistant_run(
    messages: Sequence[Mapping[str, Any]],
    index: int,
) -> Tuple[int, List[str], List[Tuple[Optional[float], Optional[float]]]]:
    """Consume consecutive assistant messages starting at ``index``.

    Returns the index of the first non-assistant message along with the text
    and audio spans of every response consumed.
    """
    texts: List[str] = []
    spans: List[Tuple[Optional[float], Optional[float]]] = []
    while index < len(messages):
        message = messages[index]
        if str(message.get("role", "")).lower() != _ROLE_ASSISTANT:
            break
        text = _extract_content(message)
        if text:
            texts.append(text)
            spans.append(_message_span_seconds(message))
        index += 1
    return index, texts, spans


def _span_bounds(
    spans: Sequence[Tuple[Optional[float], Optional[float]]],
) -> Tuple[Optional[float], Optional[float]]:
    """Return the earliest start and latest end offset present in ``spans``."""
    first_start_s: Optional[float] = None
    last_end_s: Optional[float] = None
    for start_s, end_s in spans:
        if first_start_s is None and start_s is not None:
            first_start_s = start_s
        if end_s is not None:
            last_end_s = end_s
    return first_start_s, last_end_s


def _append_turn(
    turns: List[Dict[str, Any]],
    *,
    turn_num: int,
    user_text: str,
    bot_texts: List[str],
    ttft_ms: Optional[float],
    turn_latency_ms: Optional[float],
    gaps_ms: List[float],
) -> None:
    turns.append(
        {
            _TURN: turn_num,
            _USER: user_text,
            _BOT: bot_texts,
            _TTFT_MS: ttft_ms,
            _TURN_LATENCY_MS: turn_latency_ms,
            _GAPS_MS: gaps_ms,
        }
    )


def coval_transcript_to_turn_dicts(
    messages: Sequence[Mapping[str, Any]],
) -> List[Dict[str, Any]]:
    """Convert Coval ``TranscriptMessage`` entries to eval-suite turn dicts.

    Keeps only ``user`` and ``assistant`` messages; Coval also emits
    ``system`` and ``tool`` entries (the latter when the simulated caller
    invokes a tool such as ``silence_tool`` while waiting on the agent), and
    those must not break a turn apart. When the transcript opens with
    assistant messages, they become a welcome-style turn with an empty user
    utterance.

    Latency fields are derived from Coval ``start_offset`` / ``end_offset``
    values, which are absolute call-timeline positions in **seconds**:

    - ``ttft_ms``: time from the preceding user utterance end (or call start
      for the welcome turn) until the first assistant audio in the turn
    - ``turn_latency_ms``: time from that same anchor until the last assistant
      audio in the turn ends
    - ``gaps_ms``: silence between each pair of consecutive assistant audio
      responses in the turn

    Missing or unusable offsets leave the latency fields as ``None``.
    """
    filtered = [
        message
        for message in messages
        if str(message.get("role", "")).lower() in _SPEECH_ROLES
    ]
    turns: List[Dict[str, Any]] = []
    index = 0
    turn_num = 0

    if filtered and str(filtered[0].get("role", "")).lower() == _ROLE_ASSISTANT:
        index, welcome_texts, welcome_spans = _collect_assistant_run(filtered, 0)
        if welcome_texts:
            first_start_s, last_end_s = _span_bounds(welcome_spans)
            ttft_ms, turn_latency_ms = _latency_from_anchor_ms(
                anchor_s=0.0,
                first_start_s=first_start_s,
                last_end_s=last_end_s,
            )
            _append_turn(
                turns,
                turn_num=turn_num,
                user_text="",
                bot_texts=welcome_texts,
                ttft_ms=ttft_ms,
                turn_latency_ms=turn_latency_ms,
                gaps_ms=_gaps_ms(welcome_spans),
            )
            turn_num += 1

    while index < len(filtered):
        role = str(filtered[index].get("role", "")).lower()
        if role != _ROLE_USER:
            index += 1
            continue

        user_message = filtered[index]
        user_text = _extract_content(user_message)
        _, user_end_s = _message_span_seconds(user_message)
        index += 1

        index, bot_texts, bot_spans = _collect_assistant_run(filtered, index)
        first_start_s, last_end_s = _span_bounds(bot_spans)

        if user_text or bot_texts:
            ttft_ms, turn_latency_ms = _latency_from_anchor_ms(
                anchor_s=user_end_s,
                first_start_s=first_start_s,
                last_end_s=last_end_s,
            )
            _append_turn(
                turns,
                turn_num=turn_num,
                user_text=user_text,
                bot_texts=bot_texts,
                ttft_ms=ttft_ms,
                turn_latency_ms=turn_latency_ms,
                gaps_ms=_gaps_ms(bot_spans),
            )
            turn_num += 1

    return turns
